def emit(message: str) -> None:
    line = str(message)
    print(line, flush=True)
    log = WORKING_ROOT / OUTPUT_NAME / "run.log"
    log.parent.mkdir(parents=True, exist_ok=True)
    with log.open("a", buffering=1) as handle:
        handle.write(line + "\n")


# Symbols are zero-padded codes ("000001"): never let pandas parse them as ints.
SHARD_DTYPES = {"symbol": str, "asof_date": str, "target_date": str}


def phase_log(name: str, **fields) -> None:
    emit(json.dumps({"phase": name, **fields}, ensure_ascii=False, default=str))


def sha256_file(path: Path) -> str:
    import hashlib

    digest = hashlib.sha256()
    with Path(path).open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def check_sha(label: str, path: Path, expected: str) -> str:
    actual = sha256_file(path)
    if actual != expected:
        if LOCAL_TEST:
            phase_log("sha_mismatch_ignored_local_test", label=label, actual=actual)
            return actual
        raise RuntimeError(f"{label} SHA mismatch: {actual} != {expected}")
    return actual


def extract_bundle(target: Path) -> Path:
    target.mkdir(parents=True, exist_ok=True)
    raw = base64.b64decode(EMBEDDED_KRONOS_ARCHIVE_B64.strip())
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as archive:
        archive.extractall(target)
    root = target / "Kronos"
    for required in (root / "model", root / C2_CODE_DIR / "model",
                     root / "finetune" / "val_c2_path_estimators.py"):
        if not required.exists():
            raise RuntimeError(f"Embedded archive missing {required}")
    return root


def download_model_repo(target: Path) -> Path:
    override = os.environ.get("KRONOS_MODEL_SNAPSHOT")
    if override:
        return Path(override)
    target.mkdir(parents=True, exist_ok=True)
    try:
        from modelscope.hub.snapshot_download import snapshot_download
    except ImportError:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "modelscope"])
        from modelscope.hub.snapshot_download import snapshot_download
    phase_log("download_model_repo", repo=MODEL_REPO)
    snapshot_download(MODEL_REPO, local_dir=str(target))
    return target


def resolve_tokenizer(snapshot: Path) -> Path:
    tokenizer = snapshot / "tokenizer"
    if not (tokenizer / "config.json").is_file():
        matches = sorted(snapshot.glob("**/tokenizer/config.json"))
        if not matches:
            raise RuntimeError(f"Tokenizer not found under {snapshot}")
        tokenizer = matches[0].parent
    sha = check_sha("tokenizer", tokenizer / "model.safetensors", EXPECTED_TOKENIZER_SHA256)
    phase_log("tokenizer_ready", path=str(tokenizer), sha256=sha,
              note="Kronos-Tokenizer-base; same sha as the C2 OOS kernel's tokenizer")
    return tokenizer


def resolve_release_predictor(snapshot: Path, expected: str) -> Path:
    candidates = [snapshot / "best_model", snapshot]
    candidates += [path.parent for path in sorted(snapshot.glob("**/model.safetensors"))]
    for candidate in candidates:
        weights = candidate / "model.safetensors"
        if candidate.name == "tokenizer" or not weights.is_file():
            continue
        if not (candidate / "config.json").is_file():
            continue
        if LOCAL_TEST or sha256_file(weights) == expected:
            return candidate.resolve()
    raise RuntimeError(f"Release predictor with sha {expected} not found under {snapshot}")


def find_unique(pattern: str) -> Path:
    matches = sorted({path.resolve() for path in INPUT_ROOT.glob(pattern)})
    if len(matches) != 1:
        raise RuntimeError(f"Expected one {pattern} under {INPUT_ROOT}, found {matches}")
    return matches[0]


def assert_no_sealed_package() -> None:
    """The sealed OOS package must not even be mounted (existence check only)."""
    mounted = [str(path) for path in INPUT_ROOT.glob("**/evaluation_manifest.json")]
    mounted += [str(path) for path in INPUT_ROOT.glob("**/*time_oos*")]
    if mounted:
        raise RuntimeError(f"Sealed/OOS evaluation package is mounted; refusing to run: {mounted}")


class _NullRun:
    def log(self, payload, step=None) -> None:
        return None


class SafeRun:
    def __init__(self, run=None):
        self.run = run
        self.errors = 0

    def log(self, payload, step=None) -> None:
        if self.run is None:
            return
        clean = {k: v for k, v in payload.items()
                 if v is not None and not (isinstance(v, float) and not math.isfinite(v))}
        if not clean:
            return
        try:
            self.run.log(clean, step=step)
        except Exception as error:  # noqa: BLE001
            self.errors += 1
            if self.errors <= 5:
                phase_log("swanlab_log_error", error=repr(error), keys=sorted(clean)[:6])


def resolve_swanlab_key() -> tuple[str, str]:
    key = os.environ.get("SWANLAB_API_KEY", "").strip()
    if key:
        return key, "env"
    try:
        from kaggle_secrets import UserSecretsClient

        key = (UserSecretsClient().get_secret("SWANLAB_API_KEY") or "").strip()
        if key:
            return key, "kaggle_secret"
    except Exception:  # noqa: BLE001
        pass
    return SWANLAB_API_KEY_FALLBACK, "fallback"


def start_swanlab(config: dict):
    if LOCAL_TEST or os.environ.get("KRONOS_DISABLE_SWANLAB") == "1":
        phase_log("swanlab_disabled")
        return None, _NullRun()
    try:
        subprocess.run([sys.executable, "-m", "pip", "install", "--disable-pip-version-check",
                        "--progress-bar", "off", "-q", "swanlab"], check=True)
        import swanlab

        api_key, key_source = resolve_swanlab_key()
        swanlab.login(api_key=api_key)
        run = swanlab.init(
            project=SWANLAB_PROJECT, workspace=SWANLAB_WORKSPACE,
            experiment_name=OUTPUT_NAME, id=SWANLAB_RUN_ID, resume="allow",
            tags=["kronos-base", "beta-v2.1", "c1", "validation-only", "gen-return",
                  "small-c2", "path-estimators", "dual-t4"],
            config=config,
        )
        phase_log("swanlab_ready", url=SWANLAB_URL, key_source=key_source)
        return swanlab, SafeRun(run)
    except Exception as error:  # noqa: BLE001
        phase_log("swanlab_unavailable", error=repr(error))
        return None, _NullRun()


def _clean(value):
    import numpy as np

    if isinstance(value, dict):
        return {str(k): _clean(v) for k, v in value.items() if not str(k).startswith("_")}
    if isinstance(value, (list, tuple)):
        return [_clean(v) for v in value]
    if isinstance(value, (float, np.floating)):
        return None if not math.isfinite(float(value)) else float(value)
    if isinstance(value, np.integer):
        return int(value)
    return value


class Orchestrator:
    """Parent-side bookkeeping: per-shard progress, per-arm scoring, comparison.json."""

    def __init__(self, est, working: Path, dates, contract: dict, model_info: dict,
                 run=None, started=None, analysis=None, panel=None, records=None):
        self.est = est
        self.working = Path(working)
        self.shards = self.working / "shards"
        self.results = self.working / "results"
        self.results.mkdir(parents=True, exist_ok=True)
        self.dates = list(dates)
        self.contract = contract
        self.model_info = model_info
        self.run = run or _NullRun()
        self.started = started or time.time()
        self.analysis = analysis
        self.panel = panel
        self.records = records
        self.features = None
        self.seen: dict[str, dict] = {}
        self.frames: dict[str, object] = {}
        self.summaries: dict[str, dict] = {}
        self.phase_status: dict[str, dict] = {p["key"]: {"status": "pending"} for p in PHASES}
        self.extras: dict[str, object] = {}
        self.step = 0

    def shard_path(self, phase: dict, date: str) -> Path:
        return self.shards / self.est.shard_name(phase["label"], phase["arm"], date)

    def poll(self, phase: dict) -> list[str]:
        import pandas as pd

        new = []
        for date in self.dates:
            path = self.shard_path(phase, date)
            if path.name in self.seen or not path.is_file():
                continue
            frame = pd.read_csv(path, dtype=SHARD_DTYPES)
            per = {}
            try:
                work = self.est.add_estimator_columns(frame)
                for name in self.est.ESTIMATORS:
                    per[name] = self.est.day_metrics(work, f"est_{name}")
            except Exception as error:  # noqa: BLE001 - shard already saved
                per = {"error": {"metric_error": repr(error)}}
            self.seen[path.name] = {"phase": phase["key"], "date": date, "rows": len(frame), **{
                f"{k}_ic": v.get("return10d_rank_ic") for k, v in per.items()}}
            self.step += 1
            new.append(path.name)
            done = [v["mean_ic"] for v in self.seen.values()
                    if v["phase"] == phase["key"] and v.get("mean_ic") is not None]
            payload = {"val/shards_done": self.step,
                       f"val/{phase['key']}/dates_done": len(done),
                       f"val/{phase['key']}/mean_ic_running": sum(done) / len(done) if done else None,
                       "val/elapsed_hours": (time.time() - self.started) / 3600.0}
            for name, metrics in per.items():
                payload[f"val/{phase['key']}/{name}_ic_day"] = metrics.get("return10d_rank_ic")
            if "mean" in per:
                payload[f"val/{phase['key']}/top_decile_within_ic_day"] = per["mean"].get(
                    "top_decile_within_ic")
            if phase["key"] == "b475_n5" and date in B475_VALGENIC_IC_BY_DATE and "mean" in per:
                payload["val/b475_n5/mean_ic_day_minus_valgenic"] = (
                    per["mean"]["return10d_rank_ic"] - B475_VALGENIC_IC_BY_DATE[date])
            self.run.log(payload, step=self.step)
            phase_log("shard_scored", phase_key=phase["key"], date=date, rows=len(frame),
                      **{f"{k}_ic": v.get("return10d_rank_ic") for k, v in per.items()},
                      dates_done=len(done), shards_done=self.step)
        if new:
            self.write_progress()
        return new

    def write_progress(self) -> dict:
        progress = {"kernel": KERNEL_ID, "elapsed_sec": time.time() - self.started,
                    "shards_done": self.step, "phase_status": self.phase_status,
                    "by_shard": self.seen}
        (self.results / "progress.json").write_text(
            json.dumps(_clean(progress), ensure_ascii=False, indent=2) + "\n")
        return progress

    def ready(self, phase: dict) -> bool:
        return all(self.shard_path(phase, d).is_file() for d in self.dates)

    def score(self, phase: dict) -> dict | None:
        import pandas as pd

        key = phase["key"]
        if key in self.summaries or not self.ready(phase):
            return None
        frame = pd.concat([pd.read_csv(self.shard_path(phase, d), dtype=SHARD_DTYPES) for d in self.dates],
                          ignore_index=True)
        expected = self.contract["subsample_windows"]
        if len(frame) != expected:
            raise RuntimeError(f"{key}: rows {len(frame)} != {expected}")
        result = self.est.score_arm(frame)
        info = self.model_info[phase["label"]]
        summary = {"phase_key": key, "label": phase["label"], "arm": self.est.ARMS[phase["arm"]],
                   "model_sha256": info["sha256"], "effective_batch": info["effective_batch"],
                   "model_code": info["code"], "load_kwargs": info["load_kwargs"],
                   "elapsed_sec_at_score": time.time() - self.started, **result}
        self.summaries[key] = summary
        self.frames[key] = self.est.add_estimator_columns(frame)
        stem = f"{phase['label']}__{phase['arm']}"
        self.frames[key].to_csv(self.results / f"{stem}_val_predictions.csv.gz", index=False,
                                compression="gzip")
        (self.results / f"{stem}_summary.json").write_text(
            json.dumps(_clean(summary), ensure_ascii=False, indent=2) + "\n")
        heads = {n: self.est.headline(s) for n, s in result["estimators"].items()}
        phase_log("arm_scored", phase_key=key, label=phase["label"], arm=phase["arm"],
                  samples=result["samples"], sample_count=result["sample_count"],
                  estimators={n: {k: h[k] for k in ("return10d_rank_ic_daily",
                                                    "return10d_rank_ic_pooled",
                                                    "return10d_rank_icir",
                                                    "top_bottom_decile_return10d",
                                                    "utility_rank_ic_daily",
                                                    "top_decile_within_ic")}
                              for n, h in heads.items()},
                  versus_mean={n: {"delta": (v["daily_ic"] or {}).get("mean_diff"),
                                   "t": (v["daily_ic"] or {}).get("t"),
                                   "adopt_rule1": v["rule1_adopt"]}
                               for n, v in result["versus_mean"].items()},
                  elapsed_sec=round(time.time() - self.started, 1))
        payload = {}
        for name, head in heads.items():
            for metric in ("return10d_rank_ic_daily", "return10d_rank_ic_pooled",
                           "return10d_rank_icir", "top_bottom_decile_return10d",
                           "utility_rank_ic_daily", "top_decile_within_ic"):
                payload[f"val_final/{key}/{name}/{metric}"] = head.get(metric)
        self.run.log(payload, step=max(self.step, 1))
        if key == "b475_n5":
            self.sanity_check()
        self.cross_arm()
        self.write_comparison(final=False)
        return summary

    def sanity_check(self) -> None:
        summary = self.summaries["b475_n5"]["estimators"]["mean"]
        ic = summary["return10d_rank_ic_daily"]
        low, high = SANITY_RANGE[0] - SANITY_TOLERANCE, SANITY_RANGE[1] + SANITY_TOLERANCE
        per_date = self.est.by_date(summary)
        diffs = [abs(per_date[d] - B475_VALGENIC_IC_BY_DATE[d])
                 for d in per_date if d in B475_VALGENIC_IC_BY_DATE]
        ok = low <= ic <= high
        self.extras["sanity_best475_n5_mean"] = {
            "daily_ic": ic, "reference_range": list(SANITY_RANGE), "tolerance": SANITY_TOLERANCE,
            "ok": ok, "max_abs_per_date_diff_vs_valgenic": max(diffs) if diffs else None,
            "mean_abs_per_date_diff_vs_valgenic": (sum(diffs) / len(diffs)) if diffs else None,
        }
        if ok:
            phase_log("sanity_ok", best475_n5_mean_daily_ic=ic, range=[low, high],
                      max_abs_per_date_diff=max(diffs) if diffs else None)
        else:
            phase_log("sanity_WARNING", best475_n5_mean_daily_ic=ic, range=[low, high],
                      max_abs_per_date_diff=max(diffs) if diffs else None,
                      note="Best@475 N5 mean daily IC deviates > 0.003 from 0.3141-0.3145")
        self.run.log({"val_final/sanity_best475_n5_mean_ic": ic,
                      "val_final/sanity_ok": 1.0 if ok else 0.0}, step=max(self.step, 1))

    def _style(self):
        if self.features is None and self.analysis is not None:
            labels = self.frames[next(iter(self.frames))]
            self.features = self.est.style_features(self.analysis, self.panel, self.records,
                                                    labels)
        return self.features

    def cross_arm(self) -> None:
        est = self.est
        try:
            features = self._style()
        except Exception as error:  # noqa: BLE001
            phase_log("style_features_error", error=repr(error))
            features = None
        style = self.extras.setdefault("style_shrink", {})
        for key, frame in self.frames.items():
            if features is not None and key not in style:
                try:
                    style[key] = est.style_shrink_report(self.analysis, frame, features,
                                                         "est_mean")
                    phase_log("style_shrink", phase_key=key,
                              raw=style[key]["raw"]["return10d_rank_ic_daily"],
                              shrunk=style[key]["style_shrink"]["return10d_rank_ic_daily"],
                              paired=style[key]["shrink_minus_raw"])
                except Exception as error:  # noqa: BLE001
                    phase_log("style_shrink_error", phase_key=key, error=repr(error))
        if "c2_n5" in self.frames:
            for ours in ("b475_n5", "b475_n16"):
                name = f"blend_c2_n5__{ours}"
                if ours not in self.frames or name in self.extras:
                    continue
                merged = est.merged_pair(self.frames["c2_n5"], self.frames[ours])
                grid = est.blend_grid(merged)
                blended = grid.pop("_frame")
                grid["role"] = ("pre-registered rule 2 (primary)" if ours == "b475_n5"
                                else "secondary (N16 paths; not used for selection)")
                if features is not None:
                    best = f"blend_w{grid['chosen_weight_on_c2']:.2f}"
                    try:
                        grid["style_shrink_on_chosen_blend"] = est.style_shrink_report(
                            self.analysis, blended, features, best)
                        grid["style_shrink_by_weight"] = {
                            f"{w:.2f}": est.style_shrink_report(
                                self.analysis, blended, features, f"blend_w{w:.2f}")["style_shrink"]
                            for w in est.BLEND_WEIGHTS}
                    except Exception as error:  # noqa: BLE001
                        phase_log("blend_style_error", error=repr(error))
                self.extras[name] = grid
                phase_log("blend_grid", pair=name, chosen_weight_on_c2=grid["chosen_weight_on_c2"],
                          ic_by_weight={k: v["return10d_rank_ic_daily"]
                                        for k, v in grid["by_weight"].items()},
                          chosen_vs_ours_alone=grid["chosen_vs_ours_alone"],
                          c2_minus_ours=grid["c2_minus_ours"])
                self.run.log({f"val_final/{name}/w{k}": v["return10d_rank_ic_daily"]
                              for k, v in grid["by_weight"].items()}, step=max(self.step, 1))
        if "b475_n5" in self.summaries and "b475_n16" in self.summaries:
            a = est.by_date(self.summaries["b475_n16"]["estimators"]["mean"])
            b = est.by_date(self.summaries["b475_n5"]["estimators"]["mean"])
            self.extras["b475_n16_minus_n5_mean"] = est.paired_stats(a, b)

    def decisions(self) -> dict:
        out = {}
        if "b475_n5" in self.summaries:
            vm = self.summaries["b475_n5"]["versus_mean"]
            adopted = [n for n, v in vm.items() if v["rule1_adopt"]]
            if adopted:
                best = max(adopted, key=lambda n: vm[n]["daily_ic"]["mean_diff"])
            out["rule1_path_estimator_best475_n5"] = {
                "candidates": {n: {"delta_ic": (v["daily_ic"] or {}).get("mean_diff"),
                                   "t": (v["daily_ic"] or {}).get("t"),
                                   "gain_ok": v["rule1_gain_ok"], "t_ok": v["rule1_t_ok"],
                                   "top_decile_fixed": v["rule1_top_decile_fixed"],
                                   "adopt": v["rule1_adopt"]} for n, v in vm.items()},
                "decision": best if adopted else "mean",
            }
        grid = self.extras.get("blend_c2_n5__b475_n5")
        if grid:
            out["rule2_blend"] = {"chosen_weight_on_c2": grid["chosen_weight_on_c2"],
                                  "ic_by_weight": {k: v["return10d_rank_ic_daily"]
                                                   for k, v in grid["by_weight"].items()}}
        style = self.extras.get("style_shrink", {})
        rule3 = {k: (v.get("shrink_minus_raw") or {}) | {
            "raw": v["raw"]["return10d_rank_ic_daily"],
            "style_shrink": v["style_shrink"]["return10d_rank_ic_daily"]}
            for k, v in style.items()}
        if grid and "style_shrink_on_chosen_blend" in grid:
            s = grid["style_shrink_on_chosen_blend"]
            rule3["chosen_blend"] = (s.get("shrink_minus_raw") or {}) | {
                "raw": s["raw"]["return10d_rank_ic_daily"],
                "style_shrink": s["style_shrink"]["return10d_rank_ic_daily"]}
        if rule3:
            out["rule3_style_shrink"] = rule3
        return out

    def write_comparison(self, final: bool) -> dict:
        arms = {}
        for key, summary in self.summaries.items():
            arms[key] = {
                "label": summary["label"], "arm": summary["arm"]["name"],
                "sample_count": summary["sample_count"], "model_sha256": summary["model_sha256"],
                "effective_batch": summary["effective_batch"], "model_code": summary["model_code"],
                "estimators": {n: self.est.headline(s) | {"by_date_ic": self.est.by_date(s)}
                               for n, s in summary["estimators"].items()},
                "versus_mean": summary["versus_mean"],
            }
        c2_vs = None
        if "c2_n5" in self.summaries and "b475_n5" in self.summaries:
            c2_vs = self.est.paired_stats(
                self.est.by_date(self.summaries["c2_n5"]["estimators"]["mean"]),
                self.est.by_date(self.summaries["b475_n5"]["estimators"]["mean"]))
        comparison = {
            "kernel": KERNEL_ID, "training": False, "sealed_oos_read": False,
            "sealed_oos_mounted": False, "contract": self.contract,
            "preregistration": PREREGISTRATION, "phase_order": [p["key"] for p in PHASES],
            "phase_status": self.phase_status, "models": self.model_info, "arms": arms,
            "c2_minus_best475_n5_mean": c2_vs, "extras": self.extras,
            "decisions": self.decisions(), "final": final,
            "elapsed_sec": time.time() - self.started,
        }
        text = json.dumps(_clean(comparison), ensure_ascii=False, indent=2) + "\n"
        (self.results / "comparison.json").write_text(text)
        shutil.copy2(self.results / "comparison.json", self.working / "comparison.json")
        return comparison


def run_phase(orch: Orchestrator, phase: dict, plan_base: dict, repo: Path, working: Path,
              deadline: float) -> list[int]:
    info = orch.model_info[phase["label"]]
    plan = dict(plan_base)
    plan["phase"] = {"key": phase["key"], "label": phase["label"], "arm": phase["arm"],
                     "checkpoint_dir": info["path"], "load_kwargs": info["load_kwargs"],
                     "effective_batch": info["effective_batch"]}
    plan["deadline"] = deadline
    plan_path = working / f"plan_{phase['key']}.json"
    plan_path.write_text(json.dumps(plan, ensure_ascii=False, indent=2) + "\n")
    code_paths = [str(repo), str(repo / "finetune")]
    if info["code"] != "head":
        code_paths.insert(0, str(repo / info["code"]))
    worker_script = repo / "finetune" / "val_c2_path_estimators.py"
    world = int(os.environ.get("KRONOS_WORLD_OVERRIDE", WORLD_SIZE))
    processes = []
    for rank in range(world):
        environment = os.environ.copy()
        environment.update({
            "PYTHONUNBUFFERED": "1", "CUDA_VISIBLE_DEVICES": str(rank) if not LOCAL_TEST else "",
            "KRONOS_SWEEP_RANK": str(rank), "KRONOS_SWEEP_WORLD": str(world),
            "PYTHONPATH": os.pathsep.join(code_paths + [environment.get("PYTHONPATH", "")]),
        })
        processes.append(subprocess.Popen(
            [sys.executable, "-u", str(worker_script), "--worker-plan", str(plan_path)],
            env=environment, cwd=str(working)))
    phase_log("phase_started", phase_key=phase["key"], label=phase["label"], arm=phase["arm"],
              workers=world, model_code=info["code"], effective_batch=info["effective_batch"],
              pythonpath_head=code_paths[0])
    while True:
        codes = [process.poll() for process in processes]
        orch.poll(phase)
        orch.score(phase)
        if all(code is not None for code in codes):
            break
        if any(code not in (None, 0) for code in codes):
            phase_log("worker_failed", phase_key=phase["key"], codes=codes)
            for process in processes:
                if process.poll() is None:
                    process.wait()
            break
        time.sleep(POLL_SECONDS)
    codes = [process.wait() for process in processes]
    orch.poll(phase)
    orch.score(phase)
    return codes


def parent_main() -> None:
    started = time.time()
    working = WORKING_ROOT / OUTPUT_NAME
    working.mkdir(parents=True, exist_ok=True)
    (working / "shards").mkdir(exist_ok=True)
    (working / "claims").mkdir(exist_ok=True)
    (working / "results").mkdir(exist_ok=True)
    if not LOCAL_TEST:
        gpu_names = subprocess.check_output(
            ["nvidia-smi", "--query-gpu=name", "--format=csv,noheader"], text=True
        ).strip().splitlines()
        if len(gpu_names) != WORLD_SIZE or any("T4" not in name for name in gpu_names):
            raise RuntimeError(f"Expected exactly two Tesla T4 GPUs, found {gpu_names}")
        phase_log("gpu", names=gpu_names)
    phase_log("start", kernel=KERNEL_ID, training=False, sealed_oos_read=False,
              order=[p["key"] for p in PHASES], swanlab=SWANLAB_URL, local_test=LOCAL_TEST)
    assert_no_sealed_package()

    repo = extract_bundle(working / "src")
    sys.path.insert(0, str(repo))
    sys.path.insert(0, str(repo / "finetune"))
    import pickle

    import val_c2_path_estimators as est

    snapshot = download_model_repo(working / "pretrained")
    tokenizer = resolve_tokenizer(snapshot)
    model_info = {}
    for label, spec in MODELS.items():
        if spec["source"] == "modelscope":
            path = resolve_release_predictor(snapshot, spec["sha256"])
            weights = path / "model.safetensors"
        else:
            weights = find_unique(spec["glob"])
            path = weights.parent
            metric = json.loads((path / "best_metric.json").read_text())
            if not LOCAL_TEST and (int(metric.get("segment", -1)) != spec["segment"] or not
                                   math.isclose(float(metric["forecast_loss"]),
                                                spec["val_forecast_ce"], rel_tol=1e-9)):
                raise RuntimeError(f"{label} unexpected best_metric: {metric}")
        sha = check_sha(label, weights, spec["sha256"])
        config = json.loads((path / "config.json").read_text())
        load_kwargs = dict(spec["load_kwargs"])
        if LOCAL_TEST:  # tiny test models: load from their own config
            load_kwargs = {}
        model_info[label] = {"path": str(path), "sha256": sha, "code": spec["code"],
                             "load_kwargs": load_kwargs, "effective_batch": spec["effective_batch"],
                             "config": config, "note": spec["note"]}
        phase_log("model_ready", label=label, source=spec["source"], sha256=sha, path=str(path),
                  model_code=spec["code"], effective_batch=spec["effective_batch"],
                  load_kwargs=load_kwargs)

    val_data = find_unique("**/temporal_symbol_validation_v1/processed_datasets/val_data.pkl")
    val_sha = check_sha("val_data", val_data, EXPECTED_VAL_SHA256)
    labels_doc = json.loads((val_data.parent.parent / "sector_labels.json").read_text())
    sector_labels = list(labels_doc["sector_labels"])
    vocab_file = snapshot / "sector_vocabulary.json"
    vocab_match = None
    if vocab_file.is_file():
        vocab = json.loads(vocab_file.read_text())
        vocab_labels = vocab.get("sector_labels") if isinstance(vocab, dict) else vocab
        vocab_match = vocab_labels == sector_labels
        if not vocab_match and not LOCAL_TEST:
            raise RuntimeError("sector_labels.json differs from ModelScope sector_vocabulary.json")
    if not LOCAL_TEST and len(sector_labels) != EXPECTED_SECTORS:
        raise RuntimeError(f"Expected {EXPECTED_SECTORS} sectors, found {len(sector_labels)}")

    from evaluate_beta_v21_val_gen_ic import build_val_records, select_subsample_dates

    with val_data.open("rb") as handle:
        panel = pickle.load(handle)
    records = build_val_records(panel)
    all_dates = sorted({row["asof_date"] for row in records})
    dates = select_subsample_dates(all_dates, int(os.environ.get("KRONOS_VAL_DATES", "24")))
    chosen = set(dates)
    subsample = [row for row in records if row["asof_date"] in chosen]
    if not LOCAL_TEST and (len(records) != EXPECTED_VAL_SAMPLES
                           or len(all_dates) != EXPECTED_VAL_DATES
                           or tuple(dates) != EXPECTED_SUBSAMPLE_DATES
                           or len(subsample) != EXPECTED_SUBSAMPLE_WINDOWS):
        raise RuntimeError(f"Val contract drift: {len(records)}/{len(all_dates)} full, "
                           f"{len(subsample)} windows on {dates}")
    observed = sorted({str(v) for f in panel.values() for v in f["sector"].dropna().unique()})
    records_file = working / "val_subsample_records.json"
    records_file.write_text(json.dumps(subsample))
    contract = {
        "val_dataset": "temporal_symbol_validation_v1", "val_data_sha256": val_sha,
        "val_full_windows": len(records), "val_full_dates": len(all_dates),
        "subsample_rule": "np.linspace(0, n_dates-1, 24).round() over sorted signal dates; "
                          "all symbols per date (same as val-gen-ic)",
        "subsample_dates": dates, "subsample_windows": len(subsample),
        "sector_labels": len(sector_labels), "sector_labels_match_modelscope_vocab": vocab_match,
        "val_observed_sectors_subset_of_labels": set(observed) <= set(sector_labels),
        "decode": {"function": "model.kronos.auto_regressive_inference(return_samples=True)",
                   "top_k": 0, "clip": 5, "max_context": 512, "pred_len": 10, "lookback": 120,
                   "seed": est.DECODE_SEED, "seed_reset": "per (model, arm, date) task",
                   "amp": "fp16 autocast on CUDA",
                   "arms": {p["key"]: est.ARMS[p["arm"]] for p in PHASES}},
        "path_columns": f"{est.PATH_PREFIX}XX = close_d10 / last_close - 1 of sampled path XX",
        "estimators": list(est.ESTIMATORS),
        "label": "return_10d = close[asof+10]/close[asof] - 1",
        "tokenizer_sha256": EXPECTED_TOKENIZER_SHA256,
    }
    analysis = None
    try:
        analysis = est.load_analysis_module(repo)
    except Exception as error:  # noqa: BLE001
        phase_log("analysis_module_unavailable", error=repr(error))
    phase_log("inputs_resolved", **{k: v for k, v in contract.items() if k != "subsample_dates"},
              first_date=dates[0], last_date=dates[-1], n_dates=len(dates),
              models={k: {"sha256": v["sha256"], "code": v["code"],
                          "effective_batch": v["effective_batch"]} for k, v in model_info.items()})

    swanlab, run = start_swanlab({
        "kernel": KERNEL_ID, "phase_order": [p["key"] for p in PHASES],
        "model_sha256": {k: v["sha256"] for k, v in model_info.items()},
        "val_data_sha256": val_sha, "subsample_windows": len(subsample), "dates": len(dates),
        "decode": contract["decode"], "estimators": list(est.ESTIMATORS),
        "training": False, "sealed_oos_read": False,
    })
    orch = Orchestrator(est, working, dates, contract, model_info, run=run, started=started,
                        analysis=analysis, panel=panel, records=subsample)
    orch.write_comparison(final=False)
    plan_base = {"tokenizer_dir": str(tokenizer), "val_data": str(val_data),
                 "sector_labels": sector_labels, "records_file": str(records_file),
                 "shards": str(working / "shards"), "claims": str(working / "claims"),
                 "dates": dates, "kernel": KERNEL_ID}
    deadline = started + HARD_LIMIT_SECONDS
    failures = {}
    durations = {}
    for phase in PHASES:
        now = time.time()
        if not phase["required"]:
            base = durations.get("b475_n5")
            n_ratio = est.ARMS[phase["arm"]]["sample_count"] / 5.0
            estimate = None if base is None else base * n_ratio * OPTIONAL_PHASE_SAFETY + 600
            if estimate is None or now + estimate > deadline:
                orch.phase_status[phase["key"]] = {"status": "skipped_time",
                                                   "estimate_sec": estimate,
                                                   "remaining_sec": deadline - now}
                phase_log("phase_skipped", phase_key=phase["key"], estimate_sec=estimate,
                          remaining_sec=deadline - now)
                orch.write_comparison(final=False)
                continue
            phase_log("phase_estimate", phase_key=phase["key"], estimate_sec=round(estimate),
                      expected_finish_utc=time.strftime("%Y-%m-%d %H:%M:%S",
                                                        time.gmtime(now + estimate / OPTIONAL_PHASE_SAFETY)))
        if now > deadline:
            orch.phase_status[phase["key"]] = {"status": "skipped_deadline"}
            continue
        orch.phase_status[phase["key"]] = {"status": "running", "started_sec": now - started}
        orch.write_progress()
        codes = run_phase(orch, phase, plan_base, repo, working, deadline)
        durations[phase["key"]] = time.time() - now
        scored = phase["key"] in orch.summaries
        orch.phase_status[phase["key"]] = {"status": "scored" if scored else "incomplete",
                                           "worker_codes": codes,
                                           "seconds": durations[phase["key"]]}
        if any(code != 0 for code in codes) or not scored:
            failures[phase["key"]] = codes
        phase_log("phase_finished", phase_key=phase["key"], codes=codes, scored=scored,
                  seconds=round(durations[phase["key"]], 1))
        orch.write_progress()
        orch.write_comparison(final=False)
    comparison = orch.write_comparison(final=True)
    phase_log("comparison_final", decisions=_clean(comparison["decisions"]),
              phase_status=comparison["phase_status"],
              c2_minus_best475_n5_mean=_clean(comparison["c2_minus_best475_n5_mean"]))
    if swanlab is not None:
        try:
            swanlab.finish()
        except Exception as error:  # noqa: BLE001
            phase_log("swanlab_finish_error", error=repr(error))
    if failures:
        raise RuntimeError(f"Phases failed or incomplete: {failures}")
    phase_log("done", total_seconds=round(time.time() - started, 1), swanlab=SWANLAB_URL)


if __name__ == "__main__":
    parent_main()
